import pyomo.environ as pyo

DATA = {
    "towers": list(range(29)),
    "regions": list(range(33)),
    "pop": {
        0: 4901, 1: 2727, 2: 2994, 3: 2984, 4: 3693, 5: 2615, 6: 3354,
        7: 4965, 8: 4223, 9: 4738, 10: 2345, 11: 3915, 12: 4068, 13: 2613,
        14: 3140, 15: 4894, 16: 3503, 17: 3733, 18: 4275, 19: 3795,
        20: 3803, 21: 3497, 22: 2403, 23: 3441, 24: 3116, 25: 2091,
        26: 4494, 27: 3593, 28: 2090, 29: 3397, 30: 3973, 31: 2362,
        32: 2068,
    },
    "cost": {
        0: 227, 1: 355, 2: 287, 3: 487, 4: 497, 5: 412, 6: 495, 7: 294,
        8: 212, 9: 290, 10: 427, 11: 399, 12: 361, 13: 253, 14: 350,
        15: 314, 16: 234, 17: 203, 18: 257, 19: 248, 20: 406, 21: 264,
        22: 277, 23: 419, 24: 426, 25: 297, 26: 474, 27: 333, 28: 491,
    },
    "budget": 2996,
    # Region 0 explicit coverage; other regions' tower lists not provided in text,
    # so they are encoded with the mapping available (empty -> cannot be covered).
    "coverage": {
        0: [1, 2, 3, 4, 5, 6, 9, 12, 14, 15, 16, 17, 19, 26],
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.T = pyo.Set(initialize=d["towers"])
    model.R = pyo.Set(initialize=d["regions"])

    def cov_init(m):
        return [(j, i) for j in d["regions"] for i in d["coverage"].get(j, [])]

    model.COV = pyo.Set(dimen=2, initialize=cov_init)

    model.x = pyo.Var(model.T, within=pyo.Binary)
    model.y = pyo.Var(model.R, within=pyo.Binary)

    def obj_rule(m):
        return sum(d["pop"][j] * m.y[j] for j in m.R)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.maximize)

    def budget_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.T) <= d["budget"]

    model.budget = pyo.Constraint(rule=budget_rule)

    def cover_rule(m, j):
        serving = d["coverage"].get(j, [])
        return m.y[j] <= sum(m.x[i] for i in serving)

    model.cover = pyo.Constraint(model.R, rule=cover_rule)

    return model


